"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Check, Info, X } from "lucide-react";

export interface BarDataPoint {
  category: string;
  value: number;
  formattedValue?: string;
  percentage?: number;
  insight?: string;
}

interface InteractiveBarChartProps {
  data: BarDataPoint[];
  title?: string;
  valuePrefix?: string;
  valueSuffix?: string;
  territoryIndex?: number;
}

export const InteractiveBarChart: React.FC<InteractiveBarChartProps> = ({
  data,
  title,
  valuePrefix = "$",
  valueSuffix = "",
  territoryIndex,
}) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);

  if (!data || data.length === 0) {
    return (
      <div className="flex h-32 items-center justify-center text-xs text-[#A8B4CC]">
        No category data available
      </div>
    );
  }

  const maxVal = Math.max(...data.map((d) => d.value)) || 1;
  const totalVal = data.reduce((acc, d) => acc + d.value, 0) || 1;

  const handleMouseEnter = (idx: number) => {
    if (selectedIdx === null) {
      setHoveredIdx(idx);
      if (territoryIndex !== undefined && typeof window !== "undefined") {
        window.dispatchEvent(
          new CustomEvent("territory-focus", {
            detail: { territory: territoryIndex, intensity: 1.6 },
          })
        );
      }
    }
  };

  const handleMouseLeave = () => {
    if (selectedIdx === null) {
      setHoveredIdx(null);
      if (territoryIndex !== undefined && typeof window !== "undefined") {
        window.dispatchEvent(
          new CustomEvent("territory-focus", {
            detail: { territory: territoryIndex, intensity: 1.0 },
          })
        );
      }
    }
  };

  const handleClick = (idx: number) => {
    if (selectedIdx === idx) {
      // Deselect
      setSelectedIdx(null);
      setHoveredIdx(null);
      if (territoryIndex !== undefined && typeof window !== "undefined") {
        window.dispatchEvent(
          new CustomEvent("territory-focus", {
            detail: { territory: territoryIndex, intensity: 1.0 },
          })
        );
      }
    } else {
      // Select & lock
      setSelectedIdx(idx);
      setHoveredIdx(idx);
      if (territoryIndex !== undefined && typeof window !== "undefined") {
        window.dispatchEvent(
          new CustomEvent("territory-focus", {
            detail: { territory: territoryIndex, intensity: 2.2 },
          })
        );
      }
    }
  };

  const activeIdx = selectedIdx !== null ? selectedIdx : hoveredIdx;
  const selectedItem = activeIdx !== null ? data[activeIdx] : null;

  return (
    <div className="w-full space-y-3 select-none" onMouseLeave={handleMouseLeave}>
      {title && (
        <div className="flex items-center justify-between text-xs pb-1">
          <span className="font-mono font-bold uppercase tracking-wider text-[#A8B4CC]">
            {title}
          </span>
          <div className="flex items-center gap-2 font-mono text-[10px] text-[#7DB8FF]">
            <span>{selectedIdx !== null ? "Selection Locked" : "Click bar to inspect"}</span>
            {selectedIdx !== null && (
              <button
                onClick={() => setSelectedIdx(null)}
                className="hover:text-white p-0.5 rounded"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        </div>
      )}

      <div className="space-y-2">
        {data.map((item, idx) => {
          const isSelected = selectedIdx === idx;
          const isHovered = hoveredIdx === idx || isSelected;
          const isDimmed = activeIdx !== null && activeIdx !== idx;
          const pct = item.percentage ?? ((item.value / totalVal) * 100);
          const barWidth = Math.max(8, (item.value / maxVal) * 100);

          return (
            <div
              key={idx}
              onMouseEnter={() => handleMouseEnter(idx)}
              onClick={() => handleClick(idx)}
              className={`group cursor-pointer rounded-xl p-2.5 transition-all duration-200 ${
                isSelected
                  ? "bg-[rgba(40,91,255,0.40)] border border-[rgba(220,235,255,0.65)] shadow-[0_0_20px_rgba(40,91,255,0.5)] scale-[1.01]"
                  : isHovered
                  ? "bg-[rgba(40,91,255,0.25)] border border-[rgba(180,210,255,0.45)] shadow-lg"
                  : isDimmed
                  ? "opacity-40 border border-transparent"
                  : "bg-[rgba(10,24,70,0.30)] border border-[rgba(180,210,255,0.12)] hover:border-[rgba(180,210,255,0.25)]"
              }`}
            >
              <div className="flex items-center justify-between font-mono text-xs mb-1.5">
                <div className="flex items-center gap-1.5">
                  {isSelected && <Check className="h-3.5 w-3.5 text-[#7DB8FF]" />}
                  <span className={`font-semibold transition-colors ${isHovered ? "text-[#FFFFFF]" : "text-[#D7DCE7]"}`}>
                    {item.category}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-[#A8B4CC]">
                    {pct.toFixed(1)}%
                  </span>
                  <span className={`font-bold transition-colors ${isHovered ? "text-[#7DB8FF]" : "text-[#FFFFFF]"}`}>
                    {item.formattedValue || `${valuePrefix}${item.value.toLocaleString()}${valueSuffix}`}
                  </span>
                </div>
              </div>

              {/* BAR TRACK */}
              <div className="h-2 w-full overflow-hidden rounded-full bg-[rgba(255,255,255,0.08)] border border-[rgba(180,210,255,0.15)]">
                <motion.div
                  initial={{ width: 0 }}
                  whileInView={{ width: `${barWidth}%` }}
                  viewport={{ once: false }}
                  transition={{ duration: 0.65, delay: idx * 0.08, ease: "easeOut" }}
                  className={`h-full rounded-full transition-all duration-200 ${
                    isSelected
                      ? "bg-gradient-to-r from-[#285BFF] via-[#7DB8FF] to-[#FFFFFF] shadow-[0_0_16px_rgba(255,255,255,0.9)]"
                      : isHovered
                      ? "bg-gradient-to-r from-[#285BFF] via-[#7DB8FF] to-[#FFFFFF] shadow-[0_0_12px_rgba(125,184,255,0.8)]"
                      : "bg-gradient-to-r from-[#102A83] to-[#285BFF]"
                  }`}
                />
              </div>
            </div>
          );
        })}
      </div>

      {/* CONTEXTUAL GLASS ANNOTATION ON SELECTION */}
      <AnimatePresence>
        {selectedIdx !== null && selectedItem && (
          <motion.div
            initial={{ opacity: 0, y: 8, height: 0 }}
            animate={{ opacity: 1, y: 0, height: "auto" }}
            exit={{ opacity: 0, y: -4, height: 0 }}
            transition={{ duration: 0.25 }}
            className="rounded-xl border border-[rgba(180,210,255,0.35)] bg-[rgba(15,35,95,0.70)] p-3.5 backdrop-blur-xl shadow-xl"
          >
            <div className="flex items-start justify-between gap-2">
              <div className="flex items-center gap-2 font-mono text-xs font-bold text-[#FFFFFF]">
                <Info className="h-4 w-4 text-[#7DB8FF]" />
                <span>{selectedItem.category}</span>
                <span className="text-[#7DB8FF]">
                  {selectedItem.formattedValue || `${valuePrefix}${selectedItem.value.toLocaleString()}${valueSuffix}`}
                </span>
                <span className="text-[10px] text-[#A8B4CC]">
                  ({((selectedItem.value / totalVal) * 100).toFixed(1)}% share)
                </span>
              </div>
              <button
                onClick={() => setSelectedIdx(null)}
                className="text-[#A8B4CC] hover:text-white transition-colors"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
            <p className="mt-1.5 font-sans text-xs text-[#D7DCE7] leading-relaxed">
              {selectedItem.insight ||
                `${selectedItem.category} represents a key performance driver with ${((selectedItem.value / totalVal) * 100).toFixed(1)}% contribution to total volume.`}
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};
